import {element as el} from './portal-ui.js';
const slides=[['01 / VẤN ĐỀ','Phụ phẩm nấm vẫn có giá trị.','Musuroom nghiên cứu hướng tận dụng phần nấm ăn phù hợp làm nguyên liệu bột gia vị, nhằm giảm lượng nguyên liệu bị bỏ đi.','tri-thuc.html?doc=phu-pham'],['02 / HƯỚNG PHÁT TRIỂN','Một hướng khai thác vị umami.','Nghiên cứu về chân nấm hương gợi mở hướng tạo nguyên liệu tăng vị. Kết quả của tác giả cần được kiểm chứng khi áp dụng cho quy trình Musuroom.','tri-thuc.html?doc=umami'],['03 / THỬ NGHIỆM','Mỗi mẻ đều cần hồ sơ.','Ghi nhận nguồn nguyên liệu, cân bằng vật chất, quy trình, mã mẫu và kết quả cảm quan. Chưa công bố công thức, hạn dùng hoặc chứng nhận khi chưa có minh chứng.','index.html#mo-phong'],['04 / ĐÁNH GIÁ','Để người thử lên tiếng.','Phiếu cảm quan đánh giá 5 tiêu chí trên thang 1–9. Cổng giám khảo trình bày điểm trung bình, trung vị, độ lệch chuẩn và biểu đồ.','trai-nghiem.html'],['05 / BƯỚC TIẾP THEO','Từ giả thuyết đến minh chứng.','Bổ sung dữ liệu mẻ thật, kết quả kiểm nghiệm và tiêu chuẩn được phép sử dụng. Mục tiêu là sản phẩm có cơ sở nghiên cứu và thông tin truy xuất rõ ràng.','dieu-khoan.html']];
let index=0;const root=document.querySelector('#pitch-slides'),counter=document.querySelector('#pitch-count');
function render(){const [step,title,body,href]=slides[index],section=el('section','','dashboard-section');section.append(el('p',step,'eyebrow'),el('h2',title),el('p',body,'lead'));const link=el('a','Mở nội dung đối chiếu ↗','arrow-link');link.href=href;section.append(link);root.replaceChildren(section);counter.textContent=`${index+1} / ${slides.length}`;document.querySelector('#pitch-back').disabled=index===0;document.querySelector('#pitch-next').disabled=index===slides.length-1;}
document.querySelector('#pitch-back').onclick=()=>{index=Math.max(0,index-1);render();};document.querySelector('#pitch-next').onclick=()=>{index=Math.min(slides.length-1,index+1);render();};document.querySelector('#pitch-full').onclick=()=>document.documentElement.requestFullscreen?.().catch(()=>{});window.addEventListener('keydown',e=>{if(e.key==='ArrowRight')document.querySelector('#pitch-next').click();if(e.key==='ArrowLeft')document.querySelector('#pitch-back').click();});render();
